```python
# schemas.py
from datetime import datetime
from typing import Literal

from ninja import Schema


class ProblemDetailSchema(Schema):
    type: str = "about:blank"
    title: str
    status: int
    detail: str | None = None
    instance: str | None = None


class OrderCreateSchema(Schema):
    product_id: int
    quantity: int

    def to_command(self) -> dict[str, int]:
        return {
            "product_id": self.product_id,
            "quantity": self.quantity,
        }


class OrderUpdateSchema(Schema):
    quantity: int

    def to_command(self) -> dict[str, int]:
        return {"quantity": self.quantity}


class OrderListSchema(Schema):
    id: int
    status: Literal["pending", "paid", "cancelled"]
    total_amount: int
    created_at: datetime


class OrderDetailSchema(OrderListSchema):
    product_id: int
    quantity: int
    updated_at: datetime

    @staticmethod
    def from_domain(order) -> "OrderDetailSchema":
        return OrderDetailSchema(
            id=order.id,
            product_id=order.product_id,
            quantity=order.quantity,
            status=order.status,
            total_amount=order.total_amount,
            created_at=order.created_at,
            updated_at=order.updated_at,
        )
```

```python
# router.py
from ninja import Router

from .schemas import (
    OrderCreateSchema,
    OrderDetailSchema,
    OrderListSchema,
    OrderUpdateSchema,
    ProblemDetailSchema,
)
from .services import (
    create_order,
    delete_order,
    get_order,
    list_orders,
    update_order,
)

router = Router(tags=["orders"])


@router.get("/", response={200: list[OrderListSchema]})
def list_order_endpoint(request):
    orders = list_orders(actor=request.auth)
    return 200, orders


@router.get("/{order_id}", response={200: OrderDetailSchema, 404: ProblemDetailSchema})
def get_order_endpoint(request, order_id: int):
    order = get_order(order_id=order_id, actor=request.auth)
    if order is None:
        return 404, ProblemDetailSchema(
            title="Order not found",
            status=404,
            detail=f"Order {order_id} does not exist.",
        )
    return 200, OrderDetailSchema.from_domain(order)


@router.post("/", response={201: OrderDetailSchema, 409: ProblemDetailSchema})
def create_order_endpoint(request, payload: OrderCreateSchema):
    result = create_order(command=payload.to_command(), actor=request.auth)
    if result.conflict:
        return 409, ProblemDetailSchema(
            title="Order conflict",
            status=409,
            detail=result.message,
        )
    return 201, OrderDetailSchema.from_domain(result.order)


@router.patch("/{order_id}", response={200: OrderDetailSchema, 404: ProblemDetailSchema})
def update_order_endpoint(request, order_id: int, payload: OrderUpdateSchema):
    order = update_order(
        order_id=order_id,
        command=payload.to_command(),
        actor=request.auth,
    )
    if order is None:
        return 404, ProblemDetailSchema(
            title="Order not found",
            status=404,
            detail=f"Order {order_id} does not exist.",
        )
    return 200, OrderDetailSchema.from_domain(order)


@router.delete("/{order_id}", response={204: None, 404: ProblemDetailSchema})
def delete_order_endpoint(request, order_id: int):
    deleted = delete_order(order_id=order_id, actor=request.auth)
    if not deleted:
        return 404, ProblemDetailSchema(
            title="Order not found",
            status=404,
            detail=f"Order {order_id} does not exist.",
        )
    return 204, None
```

```python
# api.py 또는 urls.py 근처의 NinjaAPI 등록부
from ninja import NinjaAPI

from orders.router import router as orders_router

api = NinjaAPI()
api.add_router("/orders", orders_router)
```

전제와 한계: Router는 HTTP adapter로만 두고, 비즈니스 규칙, 트랜잭션, ORM 조회, 중복 방지는 `services.py` 쪽에서 처리하는 구조입니다. POST의 `Idempotency-Key`, pagination, auth/permission 정책이 필요하면 API/DB 계약을 먼저 확정한 뒤 Router에 header binding과 OpenAPI 표시만 붙이는 쪽이 맞습니다.

